/**
 * 【スクショ解析結果整形コード】
 */
const item = $input.first()?.json || {};
let parsed = {};

let rawText = item.text || item.output || item.content?.parts?.[0]?.text || '';
if (typeof item === 'string') rawText = item;

rawText = rawText.replace(/```json/gi, '').replace(/```/g, '').trim();

try {
  parsed = JSON.parse(rawText);
} catch (e) {
  const mTitle = rawText.match(/"title":\s*"([^"]+)"/);
  const mYear = rawText.match(/"year":\s*"*(\d{4})"*?/);
  const mTmdb = rawText.match(/"tmdb_id":\s*(\d+)/);
  parsed = {
    title: mTitle ? mTitle[1] : '',
    year: mYear ? mYear[1] : null,
    tmdb_id: mTmdb ? parseInt(mTmdb[1], 10) : null
  };
}

let formInput = {};
try {
  formInput = $('On form submission').first()?.json || {};
} catch(e) {}

const cleanCountry = (c) => {
  if (!c || c === 'OTHER') return null;
  if (c.includes(':')) return c.split(':')[0].trim();
  return c;
};

const finalCountry = cleanCountry(formInput.country) || parsed.country || 'KR';
const finalMediaType = (formInput.media_type && !formInput.media_type.includes('all')) 
  ? (formInput.media_type.includes('tv') ? 'tv' : 'movie')
  : (parsed.media_type || 'movie');

const finalTmdbId = parsed.tmdb_id || (formInput.id && /^\d+$/.test(formInput.id) ? parseInt(formInput.id, 10) : null);
const finalQid = formInput.id && /^Q\d+$/i.test(formInput.id) ? formInput.id.toUpperCase() : null;

return [{
  json: {
    ...formInput,
    ...parsed,
    query: finalTmdbId ? String(finalTmdbId) : (finalQid || parsed.title || formInput.title || ''),
    id: finalTmdbId || finalQid || null,
    tmdb_id: finalTmdbId,
    wikidata_id: finalQid,
    title: parsed.title || formInput.title || '',
    origin_title: parsed.origin_title || null,
    year: parsed.year || formInput.year || null,
    director: parsed.director || null,
    cast: parsed.cast || null,
    country: finalCountry,
    target_country: finalCountry,
    media_type: finalMediaType
  }
}];
